contract ParticleInfoReader is Ownable2StepUpgradeable, UUPSUpgradeable, Multicall {
    /* Variables */
    // solhint-disable-next-line var-name-mixedcase
    address public PARTICLE_POSITION_MANAGER_ADDR;
    ParticlePositionManager internal _particlePositionManager;

    event UpdateParticleAddress(address particlePositionManager);

    // required by openzeppelin UUPS module
    // solhint-disable-next-line no-empty-blocks
    function _authorizeUpgrade(address) internal override onlyOwner {}

    constructor() {
        _disableInitializers();
    }

    function initialize(address particleAddr) external initializer {
        __UUPSUpgradeable_init();
        __Ownable_init();
        PARTICLE_POSITION_MANAGER_ADDR = particleAddr;
        _particlePositionManager = ParticlePositionManager(particleAddr);
    }

    /*==============================================================
                             Update Address
    ==============================================================*/

    /**
     * @notice Update address of particle position manager
     * @param particleAddr address of particle position manager
     */
    function updateParticleAddress(address particleAddr) external onlyOwner {
        if (particleAddr == address(0)) revert Errors.InvalidValue();
        PARTICLE_POSITION_MANAGER_ADDR = particleAddr;
        _particlePositionManager = ParticlePositionManager(particleAddr);
        emit UpdateParticleAddress(particleAddr);
    }

    /*==============================================================
                            Pool Information
    ==============================================================*/

    /**
     * @notice Helper function getting the pool and current price information
     * @param tokenId tokenId of the liquidity position NFT
     * @return token0 address of token0
     * @return token1 address of token1
     * @return fee pool fee
     * @return tickLower lower tick of the concentrated liquidity position
     * @return tickUpper upper tick of the concentrated liquidity position
     * @return liquidity amount of liquidity
     * @return sqrtRatioX96 the current price of the token pairs of this pool
     */
    function getPoolInfo(
        uint256 tokenId
    )
        external
        view
        returns (
            address token0,
            address token1,
            uint24 fee,
            int24 tickLower,
            int24 tickUpper,
            uint128 liquidity,
            uint160 sqrtRatioX96
        )
    {
        (, , token0, token1, fee, tickLower, tickUpper, liquidity, , , , ) = Base.UNI_POSITION_MANAGER.positions(
            tokenId
        );
        IUniswapV3Pool pool = IUniswapV3Pool(Base.UNI_FACTORY.getPool(token0, token1, fee));
        (sqrtRatioX96, , , , , , ) = pool.slot0();
    }

    /**
     * @notice Helper function getting the pool of different price tiers with the deepest liquidity
     * @param token0 address of token0
     * @param token1 address of token1
     * @return deepPool address of the pool with the deepest liquidity
     */
    function getDeepPool(address token0, address token1) external view returns (address deepPool) {
        uint24[3] memory feeTiers = [uint24(500), uint24(3000), uint24(10000)];
        uint128 maxLiquidity = 0;

        for (uint256 i = 0; i < feeTiers.length; i++) {
            address poolAddress = Base.UNI_FACTORY.getPool(token0, token1, feeTiers[i]);
            if (poolAddress != address(0)) {
                IUniswapV3Pool pool = IUniswapV3Pool(poolAddress);
                uint128 liquidity = pool.liquidity();
                if (liquidity > maxLiquidity) {
                    maxLiquidity = liquidity;
                    deepPool = poolAddress;
                }
            }
        }
    }

    /*==============================================================
                           Price and Liquidity
    ==============================================================*/

    /**
     * @notice Helper function getting the pool current price
     * @param token0 token0
     * @param token1 token1
     * @param fee pool fee
     * @return sqrtRatioX96 the current price of this pool
     */
    function getCurrentPrice(address token0, address token1, uint24 fee) external view returns (uint160 sqrtRatioX96) {
        IUniswapV3Pool pool = IUniswapV3Pool(Base.UNI_FACTORY.getPool(token0, token1, fee));
        (sqrtRatioX96, , , , , , ) = pool.slot0();
    }

    /**
     * @notice Helper function getting the pool current price
     * @param poolAddr address of the pool
     * @return sqrtRatioX96 the current price of this pool
     */
    function getCurrentPrice(address poolAddr) external view returns (uint160 sqrtRatioX96) {
        IUniswapV3Pool pool = IUniswapV3Pool(poolAddr);
        (sqrtRatioX96, , , , , , ) = pool.slot0();
    }

    /**
     * @notice Helper function getting the token amounts required for given liquidity and tick boundaries
     * @param liquidity desired amount of liquidity
     * @param sqrtRatioX96 current price of the token pairs of this pool
     * @param tickLower lower tick of the concentrated liquidity position
     * @param tickUpper upper tick of the concentrated liquidity position
     * @return amount0 amount for token0 at the current price
     * @return amount1 amount for token1 at the current price
     */
    function getAmountsFromLiquidity(
        uint128 liquidity,
        uint160 sqrtRatioX96,
        int24 tickLower,
        int24 tickUpper
    ) external pure returns (uint256 amount0, uint256 amount1) {
        uint160 sqrtRatioAX96 = TickMath.getSqrtRatioAtTick(tickLower);
        uint160 sqrtRatioBX96 = TickMath.getSqrtRatioAtTick(tickUpper);
        (amount0, amount1) = LiquidityAmounts.getAmountsForLiquidity(
            sqrtRatioX96,
            sqrtRatioAX96,
            sqrtRatioBX96,
            liquidity
        );
    }

    /**
     * @notice Helper function getting the token amounts required for given liquidity and tick boundaries
     * @param amount0 desired amount for token0 at the current price
     * @param amount1 desired amount for token1 at the current price
     * @param sqrtRatioX96 current price of the token pairs of this pool
     * @param tickLower lower tick of the concentrated liquidity position
     * @param tickUpper upper tick of the concentrated liquidity position
     * @return liquidity amount of corresponding liquidity
     */
    function getLiquidityFromAmounts(
        uint256 amount0,
        uint256 amount1,
        uint160 sqrtRatioX96,
        int24 tickLower,
        int24 tickUpper
    ) external pure returns (uint128 liquidity) {
        uint160 sqrtRatioAX96 = TickMath.getSqrtRatioAtTick(tickLower);
        uint160 sqrtRatioBX96 = TickMath.getSqrtRatioAtTick(tickUpper);
        liquidity = LiquidityAmounts.getLiquidityForAmounts(
            sqrtRatioX96,
            sqrtRatioAX96,
            sqrtRatioBX96,
            amount0,
            amount1
        );
    }

    /*==============================================================
                         Collateral Calculation
    ==============================================================*/
    /**
     * @notice Calculates the amount of collateral needed when borrowing liquidity from a position
     * @param liquidity amount of liquidity to borrow
     * @param tickLower lower tick of the position
     * @param tickUpper upper tick of the position
     * @return amount0 amount that the liquidity concentrates to at tickLower
     * @return amount1 amount that the liquidity concentrates to at tickHigher
     */
    function getRequiredCollateral(
        uint128 liquidity,
        int24 tickLower,
        int24 tickUpper
    ) external pure returns (uint256 amount0, uint256 amount1) {
        (amount0, amount1) = Base.getRequiredCollateral(liquidity, tickLower, tickUpper);
    }

    /*==============================================================
                         Position Information
    ==============================================================*/

    /**
     * @notice Get basic information of a liquidity position
     * @param tokenId tokenId of the liquidity position NFT
     * @return owner owner of the liquidity position
     * @return token0 address of token0
     * @return token1 address of token1
     * @return liquidity amount of current available liquidity
     * @return tickLower lower tick of the concentrated liquidity position
     * @return tickUpper upper tick of the concentrated liquidity position
     * @return token0Owed amount of token0 owed to the owner
     * @return token1Owed amount of token1 owed to the owner
     * @return renewalCutoffTime renewal cutoff time for all previous loans
     */
    function getLiquidityPosition(
        uint256 tokenId
    )
        external
        view
        returns (
            address owner,
            address token0,
            address token1,
            uint128 liquidity,
            int24 tickLower,
            int24 tickUpper,
            uint128 token0Owed,
            uint128 token1Owed,
            uint32 renewalCutoffTime
        )
    {
        (owner, renewalCutoffTime, token0Owed, token1Owed) = _particlePositionManager.lps(tokenId);
        (, , token0, token1, , tickLower, tickUpper, liquidity, , , , ) = Base.UNI_POSITION_MANAGER.positions(tokenId);
    }

    struct GetLienCache {
        uint24 token0PremiumPortion;
        uint24 token1PremiumPortion;
        int24 tickLower;
        int24 tickUpper;
        uint256 amount0;
        uint256 amount1;
    }

    /**
     * @notice Get basic information of a lien
     * @param borrower address of the borrower
     * @param lienId ID for the existing lien
     * @return tokenId tokenId of the liquidity position NFT
     * @return liquidity amount of liquidity locked in the lien
     * @return startTime start time of the lien
     * @return token0Premium amount of token0 premium locked in the lien
     * @return token1Premium amount of token1 premium locked in the lien
     * @return feeGrowthInside0LastX128 fee growth of token0 since the previous borrow/fee collection time
     * @return feeGrowthInside1LastX128 fee growth of token1 since the previous borrow/fee collection time
     * @return zeroForOne direction of the swap
     */
    function getLien(
        address borrower,
        uint96 lienId
    )
        external
        view
        returns (
            uint40 tokenId,
            uint128 liquidity,
            uint32 startTime,
            uint128 token0Premium,
            uint128 token1Premium,
            uint256 feeGrowthInside0LastX128,
            uint256 feeGrowthInside1LastX128,
            bool zeroForOne
        )
    {
        (
            tokenId,
            liquidity,
            ,
            ,
            startTime,
            feeGrowthInside0LastX128,
            feeGrowthInside1LastX128,
            zeroForOne
        ) = _particlePositionManager.liens(keccak256(abi.encodePacked(borrower, lienId)));
        (token0Premium, token1Premium) = getPremium(borrower, lienId);
    }

    /**
     * @notice Get amount of preimum
     * @param borrower address of the borrower
     * @param lienId ID for the existing lien
     * @return token0Premium amount of token0 premium locked in the lien
     * @return token1Premium amount of token1 premium locked in the lien
     */
    function getPremium(
        address borrower,
        uint96 lienId
    ) public view returns (uint128 token0Premium, uint128 token1Premium) {
        (
            uint40 tokenId,
            uint128 liquidity,
            uint24 token0PremiumPortion,
            uint24 token1PremiumPortion,
            ,
            ,
            ,

        ) = _particlePositionManager.liens(keccak256(abi.encodePacked(borrower, lienId)));

        (, , , , , int24 tickLower, int24 tickUpper, , , , , ) = Base.UNI_POSITION_MANAGER.positions(tokenId);
        (uint256 amount0, uint256 amount1) = Base.getRequiredCollateral(liquidity, tickLower, tickUpper);
        (token0Premium, token1Premium) = Base.getPremium(amount0, amount1, token0PremiumPortion, token1PremiumPortion);
    }

    struct OwedInfoCache {
        uint40 tokenId;
        uint128 liquidity;
        uint24 token0PremiumPortion;
        uint24 token1PremiumPortion;
        uint256 feeGrowthInside0LastX128;
        uint256 feeGrowthInside1LastX128;
    }

    /**
     * @notice Get the current owed fees for a position
     * @param borrower address of the borrower
     * @param lienId ID for the existing lien
     * @return token0Owed amount of token0 owed to the liquidity provider
     * @return token1Owed amount of token1 owed to the liquidity provider
     * @return token0Premium amount of token0 premium locked in the lien
     * @return token1Premium amount of token1 premium locked in the lien
     * @return collateral0 amount of token0 required by the lp (if oneForZero)
     * @return collateral1 amount of token1 required by the lp (if zeroForOne)
     */
    function getOwedInfo(
        address borrower,
        uint96 lienId
    )
        external
        view
        returns (
            uint128 token0Owed,
            uint128 token1Owed,
            uint128 token0Premium,
            uint128 token1Premium,
            uint256 collateral0,
            uint256 collateral1
        )
    {
        OwedInfoCache memory cache;
        (
            cache.tokenId,
            cache.liquidity,
            cache.token0PremiumPortion,
            cache.token1PremiumPortion,
            ,
            cache.feeGrowthInside0LastX128,
            cache.feeGrowthInside1LastX128,

        ) = _particlePositionManager.liens(keccak256(abi.encodePacked(borrower, lienId)));
        (, , token0Owed, token1Owed, token0Premium, token1Premium, collateral0, collateral1) = Base.getOwedInfo(
            DataStruct.OwedInfoParams({
                tokenId: cache.tokenId,
                liquidity: cache.liquidity,
                feeGrowthInside0LastX128: cache.feeGrowthInside0LastX128,
                feeGrowthInside1LastX128: cache.feeGrowthInside1LastX128,
                token0PremiumPortion: cache.token0PremiumPortion,
                token1PremiumPortion: cache.token1PremiumPortion
            })
        );
    }
}
"},"contracts/protocol/ParticlePositionManager.sol":{"content":"// SPDX-License-Identifier: MIT
pragma solidity 0.8.23;

import {IERC721Receiver} from "../../lib/openzeppelin-contracts/contracts/token/ERC721/IERC721Receiver.sol";
import {Multicall} from "../../lib/openzeppelin-contracts/contracts/utils/Multicall.sol";
import {ReentrancyGuard} from "../../lib/openzeppelin-contracts/contracts/security/ReentrancyGuard.sol";
import {Ownable2StepUpgradeable} from "../../lib/openzeppelin-contracts-upgradeable/contracts/access/Ownable2StepUpgradeable.sol";
import {UUPSUpgradeable} from "../../lib/openzeppelin-contracts-upgradeable/contracts/proxy/utils/UUPSUpgradeable.sol";
import {TransferHelper} from "../../lib/v3-periphery/contracts/libraries/TransferHelper.sol";

import {IParticlePositionManager} from "../interfaces/IParticlePositionManager.sol";
import {Base} from "../libraries/Base.sol";
import {LiquidityPosition} from "../libraries/LiquidityPosition.sol";
import {Lien} from "../libraries/Lien.sol";
import {SwapPosition} from "../libraries/SwapPosition.sol";
import {DataStruct, DataCache} from "../libraries/Structs.sol";
import {Errors} from "../libraries/Errors.sol";

contract ParticlePositionManager is
    IParticlePositionManager,
    Ownable2StepUpgradeable,
    UUPSUpgradeable,
    IERC721Receiver,
    ReentrancyGuard,
    Multicall
{
    using LiquidityPosition for mapping(uint256 => LiquidityPosition.Info);
    using Lien for mapping(bytes32 => Lien.Info);
    using SwapPosition for mapping(bytes32 => SwapPosition.Info);

    /* Constants */
    uint256 private constant _TREASURY_RATE_MAX = 500_000;
    uint256 private constant _FEE_FACTOR_MAX = 1_000;
    uint128 private constant _LIQUIDATION_REWARD_FACTOR_MAX = 100_000;
    uint256 private constant _LOAN_TERM_MAX = 30 days;

    /* Variables */
    uint96 private _nextRecordId; ///@dev used for both lien and swap
    uint256 private _treasuryRate;
    // solhint-disable var-name-mixedcase
    address public DEX_AGGREGATOR;
    uint256 public FEE_FACTOR;
    uint128 public LIQUIDATION_REWARD_FACTOR;
    uint256 public LOAN_TERM;
    // solhint-enable var-name-mixedcase

    /* Storage */
    mapping(uint256 => LiquidityPosition.Info) public lps; ///@dev tokenId => liquidity position
    mapping(bytes32 => Lien.Info) public liens; ///@dev (address, lienId) => lien
    mapping(address => uint256) private _treasury; ///@dev address => amount

    // required by openzeppelin UUPS module
    // solhint-disable-next-line no-empty-blocks
    function _authorizeUpgrade(address) internal override onlyOwner {}

    constructor() {
        _disableInitializers();
    }

    function initialize(
        address dexAggregator,
        uint256 feeFactor,
        uint128 liquidationRewardFactor,
        uint256 loanTerm,
        uint256 treasuryRate
    ) external initializer {
        __UUPSUpgradeable_init();
        __Ownable_init();
        DEX_AGGREGATOR = dexAggregator;
        FEE_FACTOR = feeFactor;
        LIQUIDATION_REWARD_FACTOR = liquidationRewardFactor;
        LOAN_TERM = loanTerm;
        _treasuryRate = treasuryRate;
    }

    /*==============================================================
                        Liquidity Provision Logic
    ==============================================================*/

    /// @inheritdoc IParticlePositionManager
    function mint(
        DataStruct.MintParams calldata params
    )
        external
        override
        nonReentrant
        returns (uint256 tokenId, uint128 liquidity, uint256 amount0Minted, uint256 amount1Minted)
    {
        (tokenId, liquidity, amount0Minted, amount1Minted) = lps.mint(params);
    }

    /**
     * @notice Receiver function upon ERC721 LP position transfer
     * @dev LP must use safeTransferFrom to trigger onERC721Received
     * @param from the address which previously owned the NFT
     * @param tokenId the NFT identifier which is being transferred
     */
    function onERC721Received(
        address,
        address from,
        uint256 tokenId,
        bytes calldata
    ) external override returns (bytes4) {
        if (msg.sender == Base.UNI_POSITION_MANAGER_ADDR) {
            // matched with Uniswap v3 position NFTs
            lps[tokenId] = LiquidityPosition.Info({owner: from, renewalCutoffTime: 0, token0Owed: 0, token1Owed: 0});
            (, , , , , , , uint128 liquidity, , , , ) = Base.UNI_POSITION_MANAGER.positions(tokenId);
            emit LiquidityPosition.SupplyLiquidity(tokenId, from, liquidity);
        }
        return this.onERC721Received.selector;
    }

    /*==============================================================
                       Liquidity Management Logic
    ==============================================================*/

    /// @inheritdoc IParticlePositionManager
    function increaseLiquidity(
        uint256 tokenId,
        uint256 amount0,
        uint256 amount1
    ) external override nonReentrant returns (uint128 liquidity, uint256 amount0Added, uint256 amount1Added) {
        (liquidity, amount0Added, amount1Added) = lps.increaseLiquidity(tokenId, amount0, amount1);
    }

    /// @inheritdoc IParticlePositionManager
    function decreaseLiquidity(
        uint256 tokenId,
        uint128 liquidity
    ) external override nonReentrant returns (uint256 amount0Decreased, uint256 amount1Decreased) {
        (amount0Decreased, amount1Decreased) = lps.decreaseLiquidity(tokenId, liquidity);
    }

    /// @inheritdoc IParticlePositionManager
    function collectLiquidity(
        uint256 tokenId
    ) external override nonReentrant returns (uint256 amount0Collected, uint256 amount1Collected) {
        (amount0Collected, amount1Collected) = lps.collectLiquidity(tokenId);
    }

    /// @inheritdoc IParticlePositionManager
    function reclaimLiquidity(uint256 tokenId) external override nonReentrant {
        lps.reclaimLiquidity(tokenId);
    }

    /*=============================================================
                             Open Position
    ==============================================================*/

    /// @inheritdoc IParticlePositionManager
    function openPosition(
        DataStruct.OpenPositionParams calldata params
    ) public override nonReentrant returns (uint96 lienId, uint256 collateralTo) {
        if (params.liquidity == 0) revert Errors.InsufficientBorrow();

        // local cache to avoid stack too deep
        DataCache.OpenPositionCache memory cache;

        // prepare data for swap
        (
            cache.tokenFrom,
            cache.tokenTo,
            cache.feeGrowthInside0LastX128,
            cache.feeGrowthInside1LastX128,
            cache.collateralFrom,
            collateralTo
        ) = Base.prepareLeverage(params.tokenId, params.liquidity, params.zeroForOne);

        // decrease liquidity from LP position, pull the amount to this contract
        (cache.amountFromBorrowed, cache.amountToBorrowed) = LiquidityPosition.decreaseLiquidity(
            params.tokenId,
            params.liquidity
        );
        LiquidityPosition.collectLiquidity(
            params.tokenId,
            uint128(cache.amountFromBorrowed),
            uint128(cache.amountToBorrowed),
            address(this)
        );
        if (!params.zeroForOne)
            (cache.amountFromBorrowed, cache.amountToBorrowed) = (cache.amountToBorrowed, cache.amountFromBorrowed);

        // transfer in enough collateral
        if (params.marginFrom > 0) {
            TransferHelper.safeTransferFrom(cache.tokenFrom, msg.sender, address(this), params.marginFrom);
        }
        if (params.marginTo > 0) {
            TransferHelper.safeTransferFrom(cache.tokenTo, msg.sender, address(this), params.marginTo);
        }

        // pay for fee
        if (FEE_FACTOR > 0) {
            cache.feeAmount = ((params.marginFrom + cache.amountFromBorrowed) * FEE_FACTOR) / Base.BASIS_POINT;
            cache.treasuryAmount = (cache.feeAmount * _treasuryRate) / Base.BASIS_POINT;
            _treasury[cache.tokenFrom] += cache.treasuryAmount;
            if (params.zeroForOne) {
                lps.addTokensOwed(params.tokenId, uint128(cache.feeAmount - cache.treasuryAmount), 0);
            } else {
                lps.addTokensOwed(params.tokenId, 0, uint128(cache.feeAmount - cache.treasuryAmount));
            }
        }

        // cannot swap more than available amount
        if (params.amountSwap > params.marginFrom + cache.amountFromBorrowed - cache.feeAmount)
            revert Errors.OverSpend();

        // swap to meet the collateral requirement
        (cache.amountSpent, cache.amountReceived) = Base.swap(
            cache.tokenFrom,
            cache.tokenTo,
            params.amountSwap,
            collateralTo - cache.amountToBorrowed - params.marginTo, // amount needed to meet requirement
            DEX_AGGREGATOR,
            params.data
        );

        // leftover amounts from the collateral are now premiums, and ensure enough premium is stored
        if (params.zeroForOne) {
            cache.token0PremiumPortion = Base.uint256ToUint24(
                ((params.marginFrom + cache.amountFromBorrowed - cache.feeAmount - cache.amountSpent) *
                    Base.BASIS_POINT) / cache.collateralFrom
            );
            cache.token1PremiumPortion = Base.uint256ToUint24(
                ((cache.amountReceived + cache.amountToBorrowed + params.marginTo - collateralTo) * Base.BASIS_POINT) /
                    collateralTo
            );
            if (
                cache.token0PremiumPortion < params.tokenFromPremiumPortionMin ||
                cache.token1PremiumPortion < params.tokenToPremiumPortionMin
            ) revert Errors.InsufficientPremium();
        } else {
            cache.token1PremiumPortion = Base.uint256ToUint24(
                ((params.marginFrom + cache.amountFromBorrowed - cache.feeAmount - cache.amountSpent) *
                    Base.BASIS_POINT) / cache.collateralFrom
            );
            cache.token0PremiumPortion = Base.uint256ToUint24(
                ((cache.amountReceived + cache.amountToBorrowed + params.marginTo - collateralTo) * Base.BASIS_POINT) /
                    collateralTo
            );
            if (
                cache.token0PremiumPortion < params.tokenToPremiumPortionMin ||
                cache.token1PremiumPortion < params.tokenFromPremiumPortionMin
            ) revert Errors.InsufficientPremium();
        }

        // create a new lien
        liens[keccak256(abi.encodePacked(msg.sender, lienId = _nextRecordId++))] = Lien.Info({
            tokenId: uint40(params.tokenId),
            liquidity: params.liquidity,
            token0PremiumPortion: cache.token0PremiumPortion,
            token1PremiumPortion: cache.token1PremiumPortion,
            startTime: uint32(block.timestamp),
            feeGrowthInside0LastX128: cache.feeGrowthInside0LastX128,
            feeGrowthInside1LastX128: cache.feeGrowthInside1LastX128,
            zeroForOne: params.zeroForOne
        });

        emit OpenPosition(msg.sender, lienId, collateralTo);
    }

    /*=============================================================
                             Close Position
    ==============================================================*/

    /// @inheritdoc IParticlePositionManager
    function closePosition(DataStruct.ClosePositionParams calldata params) external override nonReentrant {
        bytes32 lienKey = keccak256(abi.encodePacked(msg.sender, params.lienId));
        Lien.Info memory lien = liens.getInfo(lienKey);

        // check lien is valid
        if (lien.liquidity == 0) revert Errors.RecordEmpty();

        // delete lien from storage
        delete liens[lienKey];

        // local cache to avoid stack too deep
        DataCache.ClosePositionCache memory cache;

        // prepare data for swap back
        ///@dev the token/collateralFrom and token/collateralTo are swapped compared to openPosition
        (cache.tokenTo, cache.tokenFrom, , , cache.collateralTo, cache.collateralFrom) = Base.prepareLeverage(
            lien.tokenId,
            lien.liquidity,
            lien.zeroForOne
        );

        // get the amount of premium in the lien
        if (lien.zeroForOne) {
            (cache.tokenToPremium, cache.tokenFromPremium) = Base.getPremium(
                cache.collateralTo,
                cache.collateralFrom,
                lien.token0PremiumPortion,
                lien.token1PremiumPortion
            );
        } else {
            (cache.tokenFromPremium, cache.tokenToPremium) = Base.getPremium(
                cache.collateralFrom,
                cache.collateralTo,
                lien.token0PremiumPortion,
                lien.token1PremiumPortion
            );
        }

        // execute actual position closing
        _closePosition(params, cache, lien, msg.sender);

        emit ClosePosition(msg.sender, lien.tokenId, cache.amountFromAdd, cache.amountToAdd);
    }

    /// @inheritdoc IParticlePositionManager
    function liquidatePosition(
        DataStruct.ClosePositionParams calldata params,
        address borrower
    ) external override nonReentrant {
        bytes32 lienKey = keccak256(abi.encodePacked(borrower, params.lienId));
        Lien.Info memory lien = liens.getInfo(lienKey);

        // check lien is valid
        if (lien.liquidity == 0) revert Errors.RecordEmpty();

        // local cache to avoid stack too deep
        DataCache.ClosePositionCache memory closeCache;
        DataCache.LiquidatePositionCache memory liquidateCache;

        // get liquidation parameters
        ///@dev calculate premium outside of _closePosition to allow liquidatePosition to take reward from premium
        (
            closeCache.tokenFrom,
            closeCache.tokenTo,
            liquidateCache.tokenFromOwed,
            liquidateCache.tokenToOwed,
            closeCache.tokenFromPremium,
            closeCache.tokenToPremium,
            closeCache.collateralFrom,

        ) = Base.getOwedInfoConverted(
            DataStruct.OwedInfoParams({
                tokenId: lien.tokenId,
                liquidity: lien.liquidity,
                feeGrowthInside0LastX128: lien.feeGrowthInside0LastX128,
                feeGrowthInside1LastX128: lien.feeGrowthInside1LastX128,
                token0PremiumPortion: lien.token0PremiumPortion,
                token1PremiumPortion: lien.token1PremiumPortion
            }),
            lien.zeroForOne
        );

        // calculate liquidation reward
        liquidateCache.liquidationRewardFrom =
            ((closeCache.tokenFromPremium) * LIQUIDATION_REWARD_FACTOR) /
            uint128(Base.BASIS_POINT);
        liquidateCache.liquidationRewardTo =
            ((closeCache.tokenToPremium) * LIQUIDATION_REWARD_FACTOR) /
            uint128(Base.BASIS_POINT);
        closeCache.tokenFromPremium -= liquidateCache.liquidationRewardFrom;
