        if (premium0 > 0) {
            TransferHelper.safeTransferFrom(token0, msg.sender, address(this), premium0);
        }
        if (premium1 > 0) {
            TransferHelper.safeTransferFrom(token1, msg.sender, address(this), premium1);
        }

        emit AddPremium(msg.sender, lienId, premium0, premium1);
    }

